INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-16-z17-q92','nism-16-z17','A trader buys 4 lot(s) of a commodity future (lot size 1 units) at ₹53900 and sells at ₹53870. The profit/(loss), ignoring costs, is:','["-₹120","-₹30","₹120","-₹240"]',0,'P/L = (exit − entry) × lot size × lots.',92) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-16-z17-q93','nism-16-z17','A trader buys 5 lot(s) of a commodity future (lot size 1000 units) at ₹64800 and sells at ₹64670. The profit/(loss), ignoring costs, is:','["-₹6,50,000","₹6,50,000","-₹13,00,000","-₹1,30,000"]',0,'P/L = (exit − entry) × lot size × lots.',93) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
